internal object DuaKoDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("수탉이나 당나귀 소리 듣기", "오 알라, 나는 당신에게 당신의 현상금(수탉)을 요청합니다. — 나는 저주받은 샤이탄(당나귀)에게서 알라에게 피난처를 구합니다.", "수탉이 알라의 현상금을 구하는 소리를 듣고; 당나귀가 샤이탄에게서 피난처를 찾는 소리를 듣고.", "수탉은 천사를 보고 당나귀는 악마를 본다."),
        "dua_something_liked" to DuaText("훌륭한 것을 본 것 (악의의 눈에 대하여)", "알라께서 뜻하신 것. 오 알라, 축복을 빕니다.", "누군가의 훌륭한 것을 보면 축복을 위해 기도하십시오.", "축복을 구하는 기도는 사악한 눈을 예방합니다."),
        "dua_sell_buy_debt_repaid" to DuaText("빚을 갚을 때", "알라께서 당신의 가족과 부를 축복하시길 바랍니다.", "빚을 갚을 때 대출 기관의 경우.", "대출에 대한 반환은 감사와 상환입니다."),
        "dua_talbiyah" to DuaText("탈비야", "제가 여기 있습니다, 오 알라, 제가 여기 있습니다. 여기 있습니다. 당신은 파트너가 없습니다. 여기 있습니다. 확실히 모든 찬양과 축복과 통치는 당신의 것입니다. 파트너가 없습니다.", "ihram에 들어간 후 큰 소리로.", "Hajj와 Umrah의 상징입니다."),
        "dua_yamani_hajar" to DuaText("Rukn Yamani와 Hajar Aswad 사이", "우리 주님, 저희에게 현세와 내세에도 좋은 것을 주시고, 불의 형벌로부터 저희를 보호해 주소서.", "예멘 코너(Yemeni Corner)와 블랙 스톤(Black Stone) 사이의 타와프(tawaf)에 있습니다.", "예언자 ﷺ은 이 장소에서 tawaf로 이것을 낭송했습니다."),
        "dua_safa_marwa" to DuaText("사파와 마르와에서", "어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없습니다. 그분의 통치권과 찬양도 그분에게 있으며, 그분은 만물을 다스리는 능력을 갖고 계십니다. 오직 알라 외에는 누구도 숭배받을 권리가 없습니다. 그분은 약속을 이행하셨고, 그분의 종을 도우셨으며 홀로 동맹자들을 물리치셨습니다.", "사파(Safa)에 오르고 키블라(Qiblah)를 향합니다(3회).", "사파(Safa)와 마르와(Marwah)에 있는 선지자 ﷺ의 디크르(dhikr)."),
        "dua_arafah" to DuaText("아라파의 날 최고의 두아", "어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없습니다. 그분의 통치권과 찬양도 그분에게 있으며, 그분은 만물을 다스리는 능력을 갖고 계십니다.", "Arafah의 날 – 최고의 듀아.", "가장 좋은 두아는 아라파의 날의 두아이며, 가장 좋은 말은 이것이다."),
        "dua_takbeer_tashreeq" to DuaText("탁비르에타슈리크", "알라는 가장 위대합니다. 알라는 가장 위대합니다. 알라 외에는 신이 없습니다. 알라는 가장 위대하시며, 알라는 가장 위대하시며, 모든 찬양은 알라에게 있습니다.", "9 Dhul-Hijjah의 Fajr에서 13 Dhul-Hijjah의 Asr까지 모든 의무기도 후에.", "Ali와 Ibn Mas'ud (RA)에서 보고됨 - Hanafis에 따르면 wajib."),
        "dua_zamzam" to DuaText("잠잠 마시기", "오 알라, 유익한 지식과 풍부한 공급, 모든 질병의 치료를 간구합니다.", "Zamzam을 마실 때 원하는대로 dua를 만드십시오.", "Zamzam은 술에 취한 모든 것을 위한 것입니다(Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("창조에 대한 성찰", "우리 주님, 당신은 이 모든 것을 헛되이 창조하지 않으셨습니다. 당신께 영광을 돌립니다. 불의 형벌로부터 우리를 보호해 주십시오.", "천지창조를 생각하는 이들의 듀아.", "이해의 사람들의 듀아(ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("우리는 믿음을 부르는 소리를 들었습니다", "주님, 우리는 믿음으로 부르짖는 사람이 '주님을 믿으십시오'라고 말하는 것을 듣고 믿었습니다. 우리 주님, 우리의 죄를 용서하시고, 우리의 악행을 없애주시고, 우리를 의인과 함께 죽게 하소서.", "믿음과 의인 가운데서 죽는 것에 대한 이중입니다.", "용서와 좋은 결말을 위한 이중곡."),
        "dua_q_atina_ma_waadtana" to DuaText("약속하신 것을 우리에게 허락해 주십시오", "우리 주님, 당신의 사자들을 통해 우리에게 약속하신 것을 우리에게 허락하시고 부활의 날에 우리를 욕되게 하지 마소서. 참으로 당신은 약속을 어기지 않으십니다.", "부활의 날에 치욕을 피하십시오.", "내세에서 명예를 추구합니다."),
        "dua_q_israfana" to DuaText("우리의 과잉을 용서하십시오", "우리 주님, 우리의 죄와 지나친 일을 용서하시고, 우리의 발을 굳건하게 하시고 믿지 않는 사람들에 맞서도록 도우소서.", "초기 선지자들의 동료들의 듀아.", "확고함과 용서에 대한 이중입니다."),
        "dua_q_jamiun_nas" to DuaText("당신은 인류를 모으실 것입니다", "우리 주님, 주님께서는 의심할 여지가 없는 날에 반드시 인류를 모으실 것입니다. 실제로 알라는 약속을 어기지 않으십니다.", "부활의 날에 확실성을 확인합니다.", "지식에 확고한 기반을 둔 이들의 이중성."),
        "dua_q_maash_shahidin" to DuaText("증인들 가운데 우리를 기록해 주십시오", "우리 주여 우리가 믿었사오니 증인 중에 우리를 써 주소서.", "진리를 깨닫고 믿는 이들의 듀아.", "자신의 믿음을 받아들이는 이중."),
        "dua_q_la_tajalna_zalimin" to DuaText("범죄자들과 함께하지 않음", "우리 주님, 우리를 잘못된 사람들과 함께 두지 마십시오.", "알 아라프 사람들의 두아.", "범죄자들의 운명을 피하십시오."),
        "dua_q_tawaffana_muslimin" to DuaText("무슬림으로서의 인내와 죽음", "우리 주님, 우리에게 인내를 부어주시고 우리가 무슬림으로서 죽게 하소서.", "파라오의 마술사들이 믿었을 때의 듀아.", "시련을 견디고 믿음으로 끝나는 것입니다."),
        "dua_q_la_tajalna_fitnah" to DuaText("억압자들을 위한 재판이 아니다", "우리는 알라에게 의지합니다. 우리 주님, 우리를 불의한 사람들 때문에 시험에 들게 하지 마시고, 믿지 않는 사람들에게서 당신의 자비로 우리를 구원해 주십시오.", "무사 사람들의 듀아 (AS).", "억압과 억압자로부터 구출하기 위한 이중입니다."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua of Nuh (AS) 용서를 위한", "나의 주님, 저는 제가 알지 못하는 것을 당신께 청하지 않고 당신께 피난처를 구합니다. 그리고 당신께서 저를 용서하시고 자비를 베푸시지 않는다면 저는 패자들 가운데 있을 것입니다.", "선지자 누 (AS)의 회개의 이중.", "올바른 매너로 질문하는 교훈."),
        "dua_q_mudkhala_sidq" to DuaText("진실의 입구와 출구", "나의 주님, 나로 하여금 진리로 들어가고 진리로 나가게 하시고 당신에게서 나에게 지지하는 권위를 주소서.", "새로운 일, 집, 장소에 들어가기 전.", "두아는 히즈라 시대에 예언자 ﷺ에게 가르쳤습니다."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua of Zakariya (AS) - 나를 혼자 두지 마세요", "나의 주님, 나를 혼자 두지 마십시오. 당신은 최고의 상속자이십니다.", "아이들을 찾으시는 분들을 위해.", "이 이중을 통해 알라는 Yahya (AS)을 부여했습니다."),
        "dua_q_munzalan_mubarakan" to DuaText("축복받은 착륙지", "나의 주님, 제가 축복받은 착륙 장소에 착륙하게 하시고, 당신은 땅으로 인도하는 이들 중 최고이십니다.", "새 집으로 이사하거나 어딘가에 멈출 때 — Nuh (AS)의 dua.", "새로운 곳에서의 축복을 위한 듀아."),
        "dua_q_amanna_faghfir" to DuaText("우리는 믿으므로 용서해 주십시오", "우리 주님, 우리가 믿었으니 우리를 용서하시고 자비를 베푸소서. 주님은 가장 자비로우신 분이십니다.", "알라의 의로운 종들의 이중.", "용서와 자비를 위한 포괄적인 이중입니다."),
        "dua_q_isrif_jahannam" to DuaText("지옥의 형벌을 피하라", "우리 주님, 지옥의 형벌을 우리에게서 떠나게 하소서. 실제로 그 형벌은 항상 붙어 있습니다. 실제로 그것은 사악한 정착지이자 거주지입니다.", "가장 자비로우신 분('Ibad ar-Rahman)의 종들의 두아.", "지옥으로부터의 피난처를 위한 꾸란 두아."),
        "dua_q_hab_li_hukman" to DuaText("이브라힘의 두아 (AS) — 지혜와 잔나", "나의 주님, 나에게 지혜를 주소서, 나와 의로운 사람들과 함께 하시고, 나에게 후세에 명예로운 언급을 허락하시고, 나를 행복의 정원의 상속자로 만들어 주소서.", "지혜와 의인의 동행과 낙원을 구합니다.", "이브라힘 (AS)의 종합 듀아."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua of Lut (AS) — 내 가족을 구해주세요", "주님, 저와 제 가족을 그들이 행하는 일(결과)로부터 구원해 주십시오.", "악한 환경으로부터 가족을 보호합니다.", "악으로부터 가족을 보호합니다."),
        "dua_q_sulaiman_awzini" to DuaText("Dua of Sulaiman (AS) 감사를 위한", "나의 주님, 저와 저희 부모에게 베풀어주신 은혜에 감사하게 하시고, 주님을 기쁘시게 하는 의로운 일을 행하게 하시고, 저를 주님의 의로운 종들 가운데서 자비로 인정하게 하소서.", "축복에 감사할 수 있는 능력을 위해.", "Sulayman (AS)의 감사의 이중주."),
        "dua_q_musa_zalamtu" to DuaText("Dua of Musa (AS) — 나는 내 자신을 잘못 생각했습니다", "주님, 제가 잘못을 저질렀으니 용서해 주십시오.", "실수 후에는 즉시 회개합니다.", "알라는 무사 (AS)을 용서했습니다."),
        "dua_q_musa_najjini" to DuaText("Dua of Musa (AS) — 억압자로부터 나를 구해주세요", "나의 주님, 악한 사람들에게서 나를 구해 주십시오.", "억압자를 두려워할 때.", "이집트를 떠날 때 무사 (AS)의 듀아."),
        "dua_q_lut_unsurni" to DuaText("Dua of Lut (AS) — 부패자에 대한 지원", "나의 주님, 부패한 사람들에 맞서 나를 도와주세요.", "부패를 퍼뜨리는 자들에 맞서 도움을 청합니다.", "진리 위에 굳게 선 자들의 듀아."),
        "dua_q_hab_li_salihin" to DuaText("의로운 자녀를 위한 이브라힘의 두아 (AS)", "나의 주님, 의인 중에서 나에게 (아이를) 주소서.", "의로운 자녀를 구합니다.", "이 이중을 통해 Isma'il (AS)이 부여되었습니다."),
        "dua_q_wasita_kulla_shay" to DuaText("왕좌를 품은 천사들의 두아", "우리 주님, 당신께서는 자비와 지식으로 만물을 감싸시사 회개하고 당신의 길을 따르는 이들을 용서하시고 지옥의 형벌에서 보호해 주소서.", "보좌를 맡은 천사들이 신자들을 위해 이 두아를 만듭니다.", "천사의 두아에 포함되려는 의도로 낭송한다."),
        "dua_q_ikhwanina" to DuaText("우리보다 앞서간 형제들을 위해", "주여, 저희와 저희보다 앞서 믿음을 가진 형제들을 용서하시고, 믿는 자들을 향하여 저희 마음에 원한을 품지 마옵소서. 우리 주님, 당신은 참으로 친절하시고 자비로우십니다.", "이전에 오신 신자들과 깨끗한 마음을 위한 두아입니다.", "고귀한 동반자 (RA)과 초기 신자들을 위한 이중곡입니다."),
        "dua_q_alayka_tawakkalna" to DuaText("우리는 당신을 의지합니다 (이브라힘 AS)", "우리 주님, 우리는 당신을 의지하고 당신께로 향하며 당신께로 돌아갑니다. 우리 주님, 우리를 불신자들에게 시험에 빠뜨리지 마시고 용서해 주십시오. 우리 주님, 당신은 참으로 전능하시고 지혜로우신 분이십니다.", "이브라힘 (AS)과 그의 동료들의 두아.", "알라에 대한 의존과 그분께로 향하는 두 가지입니다."),
        "dua_q_atmim_nurana" to DuaText("우리의 빛을 완전하게 하라", "우리 주님, 우리의 빛을 완전하게 하시고 우리를 용서해 주소서. 참으로 당신은 모든 것을 다스리는 권세를 갖고 계십니다.", "부활의 날 신자들의 두아.", "시라트에 대한 빛을 요청합니다."),
        "dua_q_asiya_baytan" to DuaText("Dua of Asiya — Jannah의 집", "나의 주님, 당신 곁에 나를 위해 낙원에 집을 짓고, 파라오와 그의 행위에서 나를 구해 주시고, 악행하는 사람들에게서 나를 구해 주십시오.", "파라오의 아내 아시야의 두아.", "알라께서는 그녀를 신자들에게 모범으로 삼으셨습니다."),
        "dua_adhan_response" to DuaText("아드한에 대한 응답", "알라 외에는 힘도 없고 능력도 없습니다.", "muezzin이 말하는 것을 반복하십시오. 'Hayya 'alas-salah'와 'Hayya 'alal-falah'에서는 이렇게 말합니다.", "마음으로부터 반응하는 사람은 누구나 천국에 들어갈 것입니다."),
        "dua_adhan_shahadah" to DuaText("무아진의 샤하다 이후", "그리고 나 역시 어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없으며 무함마드 ﷺ은 그분의 종이자 사도임을 간증합니다. 나는 알라를 주님으로, 무함마드 ﷺ을 사도로, 이슬람을 종교로 기뻐합니다.", "무에진의 신앙 간증을 듣고.", "그의 죄는 용서받았습니다."),
        "dua_istiftah_baid" to DuaText("오프닝 듀아: 죄로부터 나를 멀리하라", "오 알라, 당신이 서쪽에서 동쪽을 멀리하셨듯이 나의 죄에서 나를 멀리해 주소서. 오 알라여, 흰 옷이 더러움을 씻어주듯이 나의 죄를 씻어 주소서. 오 알라여, 물과 눈과 우박으로 나의 죄를 씻어 주소서.", "오프닝 takbir 후 (사나 대신에 말할 수도 있음).", "예언자 ﷺ은 타크비르와 낭송 사이에 이것을 낭송했습니다."),
        "dua_hamdan_kathiran" to DuaText("루쿠 이후의 풍성한 칭찬", "우리 주님, 당신께는 찬양이 있습니다. 풍성하고 순결하며 복된 찬양입니다.", "Ruku에서 상승한 후 'Rabbana lakal-hamd'와 함께.", "30명이 넘는 천사들이 그것을 가장 먼저 녹음하기 위해 경주하고 있었습니다."),
